{
  "name": "rf_cal_process_pending_entry",
  "confidence": "medium",
  "docstring": "Clears a calibration entry's pending flag and, unless the entry is the active one in a running calibration state, invokes get_cal_item on the entry's saved handle before clearing the handle.",
  "subsystem": "rf",
  "var_renames": {
    "result": "entry_idx",
    "v1": "cal_table_base",
    "v2": "cal_entry",
    "v3": "cal_status",
    "v4": "saved_entry_idx",
    "v6": "cal_entry_base"
  },
  "struct_hints": [
    {
      "offset": 36,
      "meaning": "per-entry calibration item handle, relative to entry base"
    },
    {
      "offset": 46,
      "meaning": "per-entry pending/completion flag byte, relative to entry base"
    },
    {
      "offset": 190,
      "meaning": "global active calibration entry index byte"
    },
    {
      "offset": 208,
      "meaning": "global calibration status word; bit 0 gates reprocessing"
    }
  ]
}
